/* External CSS file (style.css) */

/* Style all h1 elements */
h1 {
  color: #3b82f6;
  font-size: 2rem;
  font-weight: bold;
}

/* Style all paragraphs */
p {
  color: #334155;
  font-size: 1rem;
  line-height: 1.6;
}

/* Style an element by class */
.card {
  background-color: white;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1rem;
}

/* Style an element by id */
#header {
  background-color: #0f172a;
  color: white;
  padding: 1rem;
}

/* Element selector */
p { color: gray; }

/* Class selector */
.highlight { background-color: yellow; }

/* ID selector */
#logo { width: 150px; }

/* Group selector */
h1, h2, h3 { font-family: 'Inter', sans-serif; }

/* Descendant: any <a> inside <nav> */
nav a { color: white; text-decoration: none; }

/* Direct child only */
ul > li { list-style: square; }

/* Pseudo-class: hover effect */
button:hover {
  background-color: #2563eb;
  cursor: pointer;
}

/* Focus state for accessibility */
input:focus {
  outline: 2px solid #3b82f6;
  border-color: #3b82f6;
}

/* Every other row in a table */
tr:nth-child(even) { background-color: #f8fafc; }

/* Apply border-box to everything — do this always! */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.card {
  width: 300px;
  padding: 20px;       /* space inside */
  border: 2px solid #3b82f6; /* border */
  margin: 15px;        /* space outside */
  background: white;
}

/* With border-box, the card is exactly 300px wide */
/* Without it, it would be 300 + 40 (padding) + 4 (border) = 344px */

/* Margin auto for centering */
.container {
  width: 800px;
  margin: 0 auto; /* center horizontally */
}

/* Padding shorthand */
.button {
  padding: 12px 24px; /* 12px top/bottom, 24px left/right */
}

/* Centering with Flexbox — the classic use case */
.container {
  display: flex;
  justify-content: center; /* horizontal center */
  align-items: center;     /* vertical center */
  height: 100vh;           /* full screen height */
}

/* Navigation bar */
.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  background: #0f172a;
}

/* Card row with gap */
.cards {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap; /* wrap to next line if needed */
}

.card {
  flex: 1;          /* each card takes equal space */
  min-width: 200px;
  padding: 1.5rem;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
}

/* Column layout */
.sidebar-layout {
  display: flex;
  flex-direction: row;
  gap: 2rem;
}

.sidebar { width: 250px; }
.main { flex: 1; }

/* Basic 3-column grid */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr; /* or repeat(3, 1fr) */
  gap: 1.5rem;
}

/* Full page layout */
.page-layout {
  display: grid;
  grid-template-columns: 250px 1fr;
  grid-template-rows: 60px 1fr 50px;
  height: 100vh;
}

.header  { grid-column: 1 / -1; } /* spans all columns */
.sidebar { grid-row: 2; }
.main    { grid-row: 2; }
.footer  { grid-column: 1 / -1; } /* spans all columns */

/* Responsive card grid — no media queries needed! */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1.5rem;
}

/* Spanning cells */
.featured {
  grid-column: span 2; /* takes up 2 columns */
}

/* Relative positioning */
.box {
  position: relative;
  top: 20px;   /* moves 20px down from its normal spot */
  left: 10px;  /* moves 10px right */
}

/* Absolute — positioned inside a relative parent */
.parent {
  position: relative; /* establishes positioning context */
}
.badge {
  position: absolute;
  top: 10px;
  right: 10px; /* in the top-right corner of parent */
}

/* Fixed navbar — stays at top when scrolling */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  background: #0f172a;
}

/* Sticky sidebar */
.sidebar {
  position: sticky;
  top: 80px; /* sticks 80px from top when scrolling */
}

/* ✅ Mobile-first approach */

/* Base styles — designed for mobile */
.container {
  width: 100%;
  padding: 1rem;
}

.cards {
  display: flex;
  flex-direction: column; /* stacked on mobile */
  gap: 1rem;
}

img {
  max-width: 100%;
  height: auto;
}

/* Tablet (768px and up) */
@media (min-width: 768px) {
  .container {
    padding: 1.5rem;
  }
  .cards {
    flex-direction: row; /* side by side on tablet */
  }
}

/* Desktop (1024px and up) */
@media (min-width: 1024px) {
  .container {
    max-width: 1200px;
    margin: 0 auto;
  }
}

/* Mobile-first media queries */

/* Base: mobile */
.nav { display: none; }
.menu-toggle { display: block; }

/* Tablet and up */
@media (min-width: 768px) {
  .nav { display: flex; }
  .menu-toggle { display: none; }
}

/* Desktop */
@media (min-width: 1024px) {
  .grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Dark mode */
@media (prefers-color-scheme: dark) {
  body {
    background: #0f172a;
    color: #f8fafc;
  }
}

/* Print styles */
@media print {
  .navbar, .sidebar, .ads {
    display: none;
  }
  body {
    font-size: 12pt;
    color: black;
  }
}

/* Declare variables on :root (global scope) */
:root {
  --color-primary: #3b82f6;
  --color-success: #22c55e;
  --color-danger: #ef4444;
  --color-bg: #0f172a;
  --color-text: #f8fafc;
  --border-radius: 8px;
  --font-size-base: 1rem;
  --spacing-md: 1rem;
  --spacing-lg: 2rem;
}

/* Use the variables */
body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-size: var(--font-size-base);
}

.button {
  background-color: var(--color-primary);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
}

/* Dark mode theme — just override variables! */
[data-theme="light"] {
  --color-bg: #ffffff;
  --color-text: #0f172a;
}

/* Transition: smooth hover effect */
.button {
  background-color: #3b82f6;
  transition: background-color 0.3s ease, transform 0.2s ease;
}

.button:hover {
  background-color: #2563eb;
  transform: scale(1.05); /* slightly bigger */
}

/* Keyframe animation: fade in */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

.card {
  animation: fadeIn 0.5s ease forwards;
}

/* Spinning loader */
@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.loader {
  width: 40px;
  height: 40px;
  border: 4px solid #e2e8f0;
  border-top-color: #3b82f6;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

