let user_age = 25;           // underscore (OK)
let $price = 9.99;           // dollar sign (OK)
// let 2fast = true;         // ❌ starts with number

// Variables hold different types
let name = "Bob";        // string
let age = 30;            // number
let isLoggedIn = true;   // boolean
let nothing = null;      // null
let unknown;             // undefined (not yet assigned)

// String
