let city = 'Lagos';
let template = `Learning JavaScript`;

// Number (integers and decimals are the same type)
let age = 25;
let price = 19.99;
let negative = -5;
let big = 1_000_000; // underscores for readability

// Boolean
let isActive = true;
let isLoggedIn = false;

// Null — intentionally empty
let selectedUser = null;

// Undefined — not yet assigned
let result;
console.log(result); // undefined

// Checking types with typeof
console.log(typeof "hello");    // "string"
console.log(typeof 42);         // "number"
console.log(typeof true);       // "boolean"
console.log(typeof null);       // "object" ← known JS quirk!
console.log(typeof undefined);  // "undefined"
console.log(typeof []);         // "object"
console.log(typeof {});         // "object"

let name = "Alice";
let city = "Lagos";

// Length
console.log(name.length); // 5

// Case
console.log(name.toUpperCase()); // "ALICE"
console.log(name.toLowerCase()); // "alice"

// Trim whitespace
let messy = "  hello world  ";
console.log(messy.trim()); // "hello world"

// Check content
console.log(name.includes("lic")); // true
console.log(name.startsWith("Al")); // true

// Slice (extract part)
let message = "Hello, World!";
console.log(message.slice(7, 12)); // "World"

// Replace
console.log(message.replace("World", "StackGen")); // "Hello, StackGen!"

// Split into array
let csv = "red,green,blue";
console.log(csv.split(",")); // ["red", "green", "blue"]

// Concatenation
let greeting = "Hello, " + name + "!";
console.log(greeting); // "Hello, Alice!"

// Template literal (much cleaner!)
console.log(`Hello, ${name}! You live in ${city}.`);

// String to Number
let ageInput = "25"; // from a form, comes as string
let age = Number(ageInput);
console.log(age + 5); // 30 (works correctly now)

// parseInt and parseFloat
console.log(parseInt("42px"));     // 42
console.log(parseFloat("3.14abc")); // 3.14

// NaN
let bad = Number("hello");
console.log(bad);         // NaN
console.log(isNaN(bad));  // true (use this to check!)

// Number to String
let num = 100;
console.log(String(num));   // "100"
console.log(num.toString()); // "100"

// Boolean conversion
console.log(Boolean(0));         // false
console.log(Boolean(""));        // false
console.log(Boolean(null));      // false
console.log(Boolean("hello"));   // true
console.log(Boolean(42));        // true
console.log(Boolean([]));        // true (even empty array!)

// Practical: check if input is a valid number
function isValidAge(input) {
  const num = Number(input);
  return !isNaN(num) && num > 0 && num < 150;
}

// + operator with strings
console.log("5" + 3);    // "53" ← concatenation, not addition!
console.log(5 + 3);      // 8   ← number addition
console.log("5" - 3);    // 2   ← subtraction converts string to number
console.log("5" * 2);    // 10  ← multiplication also converts

// Loose equality (==) coercion — avoid this!
