console.log("" == false);  // true ← dangerous!
console.log(null == undefined); // true ← dangerous!
console.log(1 == "1");     // true ← dangerous!

// Strict equality (===) — always use this
console.log(0 === false);  // false ← correct!
console.log(1 === "1");    // false ← correct!

// Truthy/Falsy in conditions
let username = "";  // falsy
if (username) {
  console.log("Hello, " + username);
} else {
  console.log("Please enter a username"); // This runs
}

// The fix — explicit conversion
let formInput = "42";
let num = Number(formInput); // explicitly convert
console.log(num + 8); // 50 (correct)

// if / else if / else
