  console.log(i); // prints: 1, 3
}

// Creating arrays
let numbers = [1, 2, 3, 4, 5];
let mixed = ["Alice", 25, true, null]; // can hold any types
let empty = [];

// Accessing elements (0-indexed)
console.log(numbers[0]);  // 1 (first)
console.log(numbers[4]);  // 5 (last)
console.log(numbers[numbers.length - 1]); // 5 (last, dynamic)

// Adding and removing
let fruits = ["apple", "banana"];
fruits.push("mango");        // ["apple", "banana", "mango"]
fruits.unshift("cherry");    // ["cherry", "apple", "banana", "mango"]
