let students = [
  { name: "Alice", grade: 92 },
  { name: "Bob",   grade: 74 },
  { name: "Carol", grade: 88 },
  { name: "Dave",  grade: 61 },
];

// forEach — just loop
students.forEach(s => console.log(s.name));
// Alice, Bob, Carol, Dave

// map — transform each element
let names = students.map(s => s.name);
console.log(names); // ["Alice", "Bob", "Carol", "Dave"]

let grades = students.map(s => s.grade * 1.05); // add 5%
console.log(grades); // [96.6, 77.7, 92.4, 64.05]

// filter — keep only matching elements
let passing = students.filter(s => s.grade >= 70);
console.log(passing); // Alice, Bob, Carol

// find — first match
let topStudent = students.find(s => s.grade > 90);
console.log(topStudent); // { name: "Alice", grade: 92 }

// reduce — calculate total
let total = students.reduce((sum, s) => sum + s.grade, 0);
console.log(total);         // 315
console.log(total / students.length); // 78.75 (average)

// some and every
console.log(students.some(s => s.grade > 90));  // true (Alice)
console.log(students.every(s => s.grade > 50)); // true

