async function getLessonById(req, res) {
  const { id } = req.params;

  const result = await db.query(
    "SELECT l.*, c.name as category_name FROM lessons l JOIN learning_categories c ON l.category_id = c.id WHERE l.id = $1",
    [id]
  );

  if (result.rows.length === 0) {
    return res.status(404).json({ msg: "Lesson not found" });
  }

  res.json(result.rows[0]);
}

// ── Password Hashing ──
const bcrypt = require("bcrypt");

// Registration: hash before saving
async function registerUser(email, plainPassword) {
  const saltRounds = 10; // higher = slower but more secure
  const passwordHash = await bcrypt.hash(plainPassword, saltRounds);

  await db.query(
    "INSERT INTO users (email, password_hash) VALUES ($1, $2)",
    [email, passwordHash]
  );
}

// Login: compare password with stored hash
async function loginUser(email, plainPassword) {
  const user = await db.query(
    "SELECT * FROM users WHERE email = $1", [email]
  );

  if (user.rows.length === 0) return null; // user not found

  const isMatch = await bcrypt.compare(plainPassword, user.rows[0].password_hash);
  return isMatch ? user.rows[0] : null;
}

// ── JWT ──
const jwt = require("jsonwebtoken");

// Create token on successful login
function createToken(userId) {
  const payload = { user: { id: userId } };
  return jwt.sign(payload, process.env.JWT_SECRET, { expiresIn: "5d" });
}

// Verify token in middleware
function verifyToken(token) {
  return jwt.verify(token, process.env.JWT_SECRET); // throws if invalid
}

// Frontend: store and send token
localStorage.setItem("token", token);
